using System;
using System.Collections.Generic;
using System.IO;
using System.Xml.Serialization;
namespace Downfield {
public class ClubPlayer {public string InjuryType="";
 public int Id,Team,Slot=-1,Number,Age,OVR,Speed,Hands,Power,Salary,Years=2,XP,Morale=75,InjuryWeeks,Potential;
 public string Name="",Role="";
 public int SigningCost {get{return 6+(OVR-70)*6/5;}}
 public string Line {get{return Name+" / "+Role+" / "+OVR+" OVR";}}
}
public class LeagueTeam {
 public int Id,Primary,Secondary,CoachOff,CoachDef,CoachFit;
 public string City="",Mascot="",BuildPlan="BALANCED";
 public string Name {get{return City+" "+Mascot;}}
}
public class Fixture {
 public int Id,Round,Home,Away,HomeScore,AwayScore; public bool Played;
 public int Winner {get{return HomeScore>=AwayScore?Home:Away;}}
 public bool Involves(int team){return Home==team||Away==team;}
 public int Opponent(int team){return Home==team?Away:Home;}
}
public class Standing {
 public int Team,W,L,T,PF,PA;
 public int Points {get{return W*2+T;}}
 public int Diff {get{return PF-PA;}}
}
public partial class Franchise {
 public int Version=1,UserTeam,Season=1,Round,Credits=12,NextId=1,Passing,Running,Defense,Training,TrainingRound=-1,Titles;
 public List<LeagueTeam> Teams=new List<LeagueTeam>();
 public List<ClubPlayer> Players=new List<ClubPlayer>();
 public List<Fixture> Games=new List<Fixture>();
 public List<int> Seeds=new List<int>();
 public List<string> News=new List<string>();
 public string Notice="Welcome to your front office. Build a contender.";
 public const int Cap=190,MaxRoster=30;
 public static readonly string[] Roles={"QB","RB","WR","WR","TE","OL","OL","OL","OL","OL","WR","DL","DL","DL","DL","CB","CB","LB","LB","NB","S","S"};
 public static readonly string[] Colors={"OCEAN","GOLD","CRIMSON","FOREST","VIOLET","ORANGE","ICE","BLACK","WHITE"};
 public static readonly int[] Palette={0x247AB8,0xC9AC67,0xB93848,0x318B65,0x7956B3,0xDA7934,0x71C9D9,0x262735,0xE9E4CF};
 public static readonly string[] Mascots={"CURRENT","CRESCENT","FIRE","STAMPEDE","TIDES","EVERGREENS","EMPIRE","COMETS","WOLVES","BISON","PIONEERS","THUNDER"};
 public static readonly string[] Cities={"CHICAGO","NEW ORLEANS","ATLANTA","DALLAS","MIAMI","SEATTLE","NEW YORK","LOS ANGELES","DENVER","BUFFALO","PORTLAND","NASHVILLE","AUSTIN","SAN DIEGO","ST LOUIS","SAN ANTONIO"};
 public static string SavePath {get{return Profile.SavePath+".franchise.xml";}}
 public LeagueTeam Club {get{return Teams[UserTeam];}}
 public string Stage {get{return DraftActive?"DRAFT / ROUND "+DraftRound:Round<11?"WEEK "+(Round+1)+" OF 11":Round==11?"WILD CARD":Round==12?"SEMIFINALS":Round==13?"CHAMPIONSHIP":"OFFSEASON";}}
 public Fixture UserGame {get{if(Fired||DraftActive)return null;return Games.Find(g=>g.Round==Round&&!g.Played&&g.Involves(UserTeam));}}
 public bool Complete {get{return Round>=14;}}
 public int Payroll(int team){int n=0;foreach(ClubPlayer p in Players)if(p.Team==team)n+=p.Salary;return n;}
 public List<ClubPlayer> Squad(int team){return Players.FindAll(p=>p.Team==team);}
 public List<ClubPlayer> FreeAgents(){List<ClubPlayer> a=Players.FindAll(p=>p.Team==-1);a.Sort((x,y)=>y.OVR.CompareTo(x.OVR));return a;}
 public ClubPlayer Starter(int team,int slot){return Players.Find(p=>p.Team==team&&p.Slot==slot);}
 public int Rating(int team,bool defense){int n=0,c=0;foreach(ClubPlayer p in Players)if(p.Team==team&&p.Slot>=(defense?11:0)&&p.Slot<(defense?22:11)){n+=p.InjuryWeeks>0?70:p.OVR;c++;}return c==0?70:n/c;}
 public static Franchise Create(Profile old,Roster legacy){Franchise f=new Franchise();f.UserTeam=Math.Min(11,legacy.Team);f.Credits=old.Credits;f.Passing=old.Passing;f.Running=old.Running;f.Defense=old.Defense;Random r=new Random(7213);
  for(int t=0;t<12;t++){LeagueTeam team=new LeagueTeam();team.Id=t;team.City=Cities[t];team.Mascot=Mascots[t];team.Primary=t==1?7:t%7;team.Secondary=t==1?1:8;f.Teams.Add(team);for(int slot=0;slot<25;slot++){string role=slot<22?Roles[slot]:slot==22?"QB":slot==23?"RB":"WR";ClubPlayer p=f.Generate(r,role,Math.Min(88,70+r.Next(15)+(t%3)),t);p.Slot=slot<22?slot:-1;p.Number=NumberFor(slot);f.Players.Add(p);}}
  foreach(int i in legacy.Signed)if(i>=0&&i<Roster.Market.Length){Recruit c=Roster.Market[i];string role=c.Role=="DEF"?"LB":c.Role;ClubPlayer p=f.Generate(r,role,c.OVR,f.UserTeam);p.Name=c.Name;p.Speed=c.Speed;p.Hands=c.Hands;p.Power=c.Power;ClubPlayer starter=f.Players.Find(q=>q.Team==f.UserTeam&&q.Role==role&&q.Slot>=0);if(starter!=null){p.Slot=starter.Slot;p.Number=starter.Number;f.Players.Remove(starter);}f.Players.Add(p);}
  f.MakeMarket();f.Schedule();f.EnsureLeagueDevelopment();f.EnsureCareer();f.EnsureJerseyNumbers();return f;
 }
 static int NumberFor(int slot){int[] n={7,22,81,88,85,60,61,62,63,64,11,90,91,92,93,24,28,54,55,21,31,32,12,26,18};return n[slot%25];}
 ClubPlayer Generate(Random r,string role,int ovr,int team){string[] first={"J","C","D","M","R","T","A","K","L","S"};string[] last={"HAYES","VALE","REED","PARK","STONE","BELL","WALKER","BROOKS","TURNER","JAMES","COLE","RIVERS","KING","CHASE","BLAKE","SUTTON","MILES","HILL","FORD","PRICE","YOUNG","WARD","GRANT","ROSS"};ClubPlayer p=new ClubPlayer();p.Id=NextId++;p.Team=team;p.Name=first[r.Next(first.Length)]+" "+last[r.Next(last.Length)];while(Players.Exists(existing=>existing.Team==team&&existing.Name==p.Name))p.Name=first[r.Next(first.Length)]+" "+last[r.Next(last.Length)];p.Role=role;p.OVR=ovr;p.Age=21+r.Next(10);p.Speed=Bound(ovr+r.Next(-7,8));p.Hands=Bound(ovr+r.Next(-7,8));p.Power=Bound(ovr+r.Next(-7,8));p.Salary=ContractSalary(ovr);p.Number=1+r.Next(98);p.Years=2+r.Next(2);p.Potential=Math.Min(99,ovr+5+p.Id*7%15);return p;}
 static int Bound(int n){return Math.Max(70,Math.Min(99,n));}
 void MakeMarket(){Random r=new Random(9981+Season);string[] roles={"QB","RB","WR","TE","OL","DL","CB","LB","NB","S"};for(int i=0;i<30;i++)Players.Add(Generate(r,roles[i%10],70+i,-1));}
 void Schedule(){Games.Clear();Seeds.Clear();int[] ring=new int[12];for(int i=0;i<12;i++)ring[i]=(i+Season-1)%12;for(int round=0;round<11;round++){for(int i=0;i<6;i++)AddGame(round,round%2==0?ring[i]:ring[11-i],round%2==0?ring[11-i]:ring[i]);int end=ring[11];for(int i=11;i>1;i--)ring[i]=ring[i-1];ring[1]=end;}Round=0;}
 void AddGame(int round,int home,int away){Fixture g=new Fixture();g.Id=Games.Count+1;g.Round=round;g.Home=home;g.Away=away;Games.Add(g);}
 public List<Standing> Table(){List<Standing> rows=new List<Standing>();for(int i=0;i<12;i++){Standing s=new Standing();s.Team=i;rows.Add(s);}foreach(Fixture g in Games)if(g.Played&&g.Round<11){Standing h=rows[g.Home],a=rows[g.Away];h.PF+=g.HomeScore;h.PA+=g.AwayScore;a.PF+=g.AwayScore;a.PA+=g.HomeScore;if(g.HomeScore>g.AwayScore){h.W++;a.L++;}else if(g.HomeScore<g.AwayScore){a.W++;h.L++;}else{a.T++;h.T++;}}rows.Sort((a,b)=>{int v=b.Points.CompareTo(a.Points);if(v==0)v=b.Diff.CompareTo(a.Diff);if(v==0)v=b.PF.CompareTo(a.PF);return v==0?a.Team.CompareTo(b.Team):v;});return rows;}
 public List<int> ProjectedSeeds(){if(Seeds.Count>0)return new List<int>(Seeds);List<int> a=new List<int>();List<Standing> rows=Table();for(int i=0;i<6;i++)a.Add(rows[i].Team);return a;}
 public void Log(string n){Notice=n;News.Insert(0,"S"+Season+" "+Stage+": "+n);if(News.Count>30)News.RemoveAt(30);}
 public bool Sign(int id){if(!CanManageClub())return false;ClubPlayer p=Players.Find(x=>x.Id==id&&x.Team==-1);if(p==null)return false;if(Squad(UserTeam).Count>=MaxRoster){Notice="Roster full: release or trade a player first.";return false;}if(Payroll(UserTeam)+p.Salary>Cap){Notice="Not enough salary cap space.";return false;}if(Credits<p.SigningCost){Notice="Need "+p.SigningCost+" credits for this contract.";return false;}Credits-=p.SigningCost;p.Team=UserTeam;p.Years=3;p.Slot=-1;Log("Signed "+p.Line+". Set his role in View Roster.");Save();return true;}
 public List<int> EligibleSlots(ClubPlayer p){List<int> slots=new List<int>();for(int i=0;i<22;i++)if(Roles[i]==p.Role)slots.Add(i);return slots;}
 public void StartPlayer(int id,int slot){if(!CanManageClub())return;ClubPlayer p=Players.Find(x=>x.Id==id&&x.Team==UserTeam);if(p==null||slot<0||slot>=22||Roles[slot]!=p.Role)return;ClubPlayer old=Starter(UserTeam,slot);int prior=p.Slot;if(old!=null&&old!=p)old.Slot=prior;p.Slot=slot;Log(p.Name+" starts at "+p.Role+" slot "+(slot+1)+".");Save();}
 public bool Release(int id){if(!CanManageClub())return false;ClubPlayer p=Players.Find(x=>x.Id==id&&x.Team==UserTeam);if(p==null)return false;if(p.Slot>=0){Notice="Move a reserve into this starting slot before release.";return false;}p.Team=-1;p.Years=2;Log("Released "+p.Name+". Salary space returned.");Save();return true;}
 public bool Renew(int id){if(!CanManageClub())return false;ClubPlayer p=Players.Find(x=>x.Id==id&&x.Team==UserTeam);if(p==null)return false;int cost=3+(p.OVR-70)/3;int salary=ContractSalary(p.OVR);if(Payroll(UserTeam)-p.Salary+salary>Cap){Notice="Renewal exceeds the $190 salary cap. Make roster space first.";return false;}if(p.Years>=4){Notice="Contract already runs four seasons.";return false;}if(Credits<cost){Notice="Renewal needs "+cost+" credits.";return false;}Credits-=cost;p.Salary=salary;p.Years=Math.Min(4,p.Years+2);Log(p.Name+" renewed: "+p.Years+" seasons.");Save();return true;}
 public int TradeCost(ClubPlayer outgoing,ClubPlayer incoming){return Math.Max(0,(incoming.OVR-outgoing.OVR)*2+(incoming.Age<25?2:0));}
 public bool Trade(int outgoing,int incoming){if(!CanManageClub())return false;ClubPlayer a=Players.Find(p=>p.Id==outgoing&&p.Team==UserTeam),b=Players.Find(p=>p.Id==incoming&&p.Team>=0&&p.Team!=UserTeam);if(a==null||b==null)return false;if(Round>=8){Notice="Trade deadline passed. Trading reopens next season.";return false;}if(a.Role!=b.Role||b.OVR>a.OVR+9){Notice="Other club rejects this position/value mismatch.";return false;}int fee=TradeCost(a,b);if(Credits<fee){Notice="Need "+fee+" credits to balance this trade.";return false;}int team=b.Team;if(Payroll(UserTeam)-a.Salary+b.Salary>Cap||Payroll(team)-b.Salary+a.Salary>Cap){Notice="Trade would exceed a club's salary cap.";return false;}int slot=a.Slot;a.Team=team;a.Slot=b.Slot;b.Team=UserTeam;b.Slot=slot;Credits-=fee;Log("Traded "+a.Name+" for "+b.Name+" / "+fee+" credits.");Save();return true;}
 public bool Hire(int type,int level){if(!CanManageClub())return false;int current=type==0?Club.CoachOff:type==1?Club.CoachDef:Club.CoachFit;int cost=5+level*5;if(level<=current){Notice="That staff tier is already hired.";return false;}if(Credits<cost){Notice="Need "+cost+" credits to hire this coach.";return false;}Credits-=cost;if(type==0)Club.CoachOff=level;else if(type==1)Club.CoachDef=level;else Club.CoachFit=level;Log(new string[]{"Offensive","Defensive","Conditioning"}[type]+" coach hired at tier "+level+".");Save();return true;}
 public bool Train(int focus){if(!CanManageClub())return false;if(TrainingRound==Round){Notice="Training is complete for this week.";return false;}if(Credits<3){Notice="Training costs three credits.";return false;}Training=focus;TrainingRound=Round;Credits-=3;int count=0;foreach(ClubPlayer p in Players)if(p.Team==UserTeam&&(focus==0?(p.Role=="QB"||p.Role=="WR"||p.Role=="TE"):focus==1?(p.Role=="RB"||p.Role=="OL"):p.Slot>=11)){p.XP+=2+Club.CoachFit;p.Morale=Math.Min(100,p.Morale+3);Develop(p);count++;}Log("Trained "+count+" players. XP carries toward development.");Save();return true;}
 static void Develop(ClubPlayer p){int need=p.Age<26?8:12;if(p.XP>=need&&p.OVR<99){p.XP-=need;p.OVR++;p.Speed=Bound(p.Speed+1);p.Hands=Bound(p.Hands+1);p.Power=Bound(p.Power+1);}}
 public bool Upgrade(int unit){if(!CanManageClub())return false;int lv=unit==0?Passing:unit==1?Running:Defense,cost=4+lv*3;if(lv>=5){Notice="Facility at maximum level.";return false;}if(Credits<cost){Notice="Facility upgrade needs "+cost+" credits.";return false;}Credits-=cost;if(unit==0)Passing++;else if(unit==1)Running++;else Defense++;Log("Facility upgraded. Applies next match.");Save();return true;}
 public bool Relocate(int city){if(!CanManageClub())return false;if(city<0||city>=Cities.Length)return false;foreach(LeagueTeam t in Teams)if(t.Id!=UserTeam&&t.City==Cities[city]){Notice="That city already has a club.";return false;}if(Club.City==Cities[city])return false;if(Credits<15){Notice="Relocation requires 15 credits.";return false;}Credits-=15;Club.City=Cities[city];Log("Welcome to "+Club.Name+". Roster and league record retained.");Save();return true;}
 public void Edit(int mascot,int primary,int secondary){Club.Mascot=Mascots[Math.Max(0,Math.Min(11,mascot))];Club.Primary=Math.Max(0,Math.Min(8,primary));Club.Secondary=Math.Max(0,Math.Min(8,secondary));if(Club.Primary==Club.Secondary)Club.Secondary=(Club.Primary+1)%9;Log("Brand updated: "+Club.Name+".");Save();}
 public bool TakeOver(int team){return JoinClub(team);}bool LegacyTakeOver(int team){if(team<0||team>=12||Round!=0||Games.Exists(g=>g.Played)){Notice="Choose your club before playing the season opener.";return false;}UserTeam=team;Log("You now manage "+Club.Name+".");Save();return true;}
 void Simulate(Fixture g,bool record=true){Random r=new Random(Season*10099+g.Id*173);int hr=(Rating(g.Home,false)-Rating(g.Away,true))/2+Teams[g.Home].CoachOff*2-Teams[g.Away].CoachDef;int ar=(Rating(g.Away,false)-Rating(g.Home,true))/2+Teams[g.Away].CoachOff*2-Teams[g.Home].CoachDef;g.HomeScore=Math.Max(0,10+r.Next(25)+hr);g.AwayScore=Math.Max(0,7+r.Next(25)+ar);if(g.Round>=11&&g.HomeScore==g.AwayScore)g.HomeScore+=3;g.Played=true;if(record){SimulatedBox(g,g.Home,g.HomeScore);SimulatedBox(g,g.Away,g.AwayScore);}}
 public bool FinishGame(int fixtureId,int userScore,int opponentScore,System.Collections.Generic.List<int> injuries=null,List<BoxLine> box=null,List<MatchInjury> injuryReports=null){Fixture g=Games.Find(x=>x.Id==fixtureId&&x.Round==Round&&!x.Played&&x.Involves(UserTeam));if(g==null||Fired)return false;EnsureCareer();bool overtime=Round>=11&&userScore==opponentScore;if(overtime){Random r=new Random(Season*817+g.Id);int us=Rating(UserTeam,false)+Rating(UserTeam,true),them=Rating(g.Opponent(UserTeam),false)+Rating(g.Opponent(UserTeam),true);if(r.Next(200)<100+(us-them)/2)userScore+=3;else opponentScore+=3;}g.HomeScore=g.Home==UserTeam?userScore:opponentScore;g.AwayScore=g.Away==UserTeam?userScore:opponentScore;g.Played=true;CoachResult(g);if(box!=null)AddBox(UserTeam,box);else SimulatedBox(g,UserTeam,userScore);SimulatedBox(g,g.Opponent(UserTeam),opponentScore);SettleBusiness(g,userScore,opponentScore);foreach(ClubPlayer p in Players)if(p.Team==UserTeam&&p.InjuryWeeks==0){p.XP+=p.Slot>=0?2:1;p.Morale=Math.Max(30,Math.Min(100,p.Morale+(userScore>opponentScore?3:-2)));Develop(p);}Log((overtime?"OVERTIME SIM: ":"")+Club.Mascot+" "+userScore+" - "+opponentScore+" "+Teams[g.Opponent(UserTeam)].Mascot);CompleteRound();if(injuries!=null)foreach(int id in injuries){ClubPlayer hurt=Players.Find(p=>p.Id==id&&p.Team==UserTeam);if(hurt!=null){MatchInjury detail=injuryReports==null?null:injuryReports.Find(report=>report.PlayerId==id);hurt.InjuryWeeks=detail==null?2+(hurt.Id+Season+Round)%4:detail.Weeks;hurt.InjuryType=detail==null?"BIG HIT":detail.Type;Log(hurt.Name+" injured / "+hurt.InjuryWeeks+" weeks recovery.");}}if(injuryReports!=null)foreach(MatchInjury report in injuryReports){ClubPlayer hurt=Players.Find(p=>p.Id==report.PlayerId&&(p.Team==g.Home||p.Team==g.Away));if(hurt!=null){hurt.InjuryWeeks=report.Weeks;hurt.InjuryType=report.Type;}}Save();return true;}
 public void SimNext(){if(!CanManageClub())return;if(DraftActive){AutoDraft();if(DraftActive)return;}Fixture g=UserGame;if(g==null){Advance();return;}Fixture copy=new Fixture();copy.Id=g.Id;copy.Round=g.Round;copy.Home=g.Home;copy.Away=g.Away;Simulate(copy,false);List<int> injuries=new List<int>();Random medical=new Random(Season*773+g.Id);if(medical.NextDouble()<.28-Club.CoachFit*.04){ClubPlayer hurt=Starter(UserTeam,medical.Next(22));if(hurt!=null&&hurt.InjuryWeeks==0)injuries.Add(hurt.Id);}FinishGame(g.Id,g.Home==UserTeam?copy.HomeScore:copy.AwayScore,g.Home==UserTeam?copy.AwayScore:copy.HomeScore,injuries);}public void Advance(){if(Complete||DraftActive)return;if(UserGame!=null){Notice="Play your scheduled game before advancing the league.";return;}CompleteRound();Save();}
 void CompleteRound(){IdleWeekCosts();foreach(ClubPlayer p in Players)if(p.InjuryWeeks>0)p.InjuryWeeks--;foreach(Fixture g in Games)if(g.Round==Round&&!g.Played)Simulate(g);foreach(Fixture fixture in Games)if(fixture.Round==Round){Random medical=new Random(Season*1207+fixture.Id);foreach(int team in new int[]{fixture.Home,fixture.Away})if(team!=UserTeam&&medical.NextDouble()<.21){ClubPlayer hurt=Starter(team,medical.Next(22));if(hurt!=null&&hurt.InjuryWeeks==0){hurt.InjuryWeeks=2+medical.Next(4);hurt.InjuryType="BIG HIT";}}}CpuWeek();Round++;if(Round==11){List<Standing> rows=Table();Seeds.Clear();for(int i=0;i<6;i++)Seeds.Add(rows[i].Team);AddGame(11,Seeds[2],Seeds[5]);AddGame(11,Seeds[3],Seeds[4]);Log("Playoffs set. Top two seeds receive a bye.");}else if(Round==12){List<int> winners=Winners(11);winners.Sort((a,b)=>Seeds.IndexOf(a).CompareTo(Seeds.IndexOf(b)));AddGame(12,Seeds[0],winners[1]);AddGame(12,Seeds[1],winners[0]);}else if(Round==13){List<int> winners=Winners(12);AddGame(13,winners[0],winners[1]);}else if(Round==14){Fixture final=Games.Find(x=>x.Round==13);if(final.Winner==UserTeam){Titles++;Credits+=8;}ArchiveSeason();Log(Teams[final.Winner].Name+" are league champions!");}}
 List<int> Winners(int round){List<int> a=new List<int>();foreach(Fixture g in Games)if(g.Round==round)a.Add(g.Winner);return a;}
 public void NextSeason(){if(!Complete){Notice="Finish the season before opening a new one.";return;}ArchiveSeason();PrepareLeagueOffseason();Production.Clear();Season++;Credits+=8;Players.RemoveAll(p=>p.Team==-1);AgeAndRetire();foreach(ClubPlayer p in Players)if(p.Years<=0){p.Team=-1;p.Slot=-1;}FillVacancies();MakeMarket();Schedule();TrainingRound=-1;BeginDraft();Log("New season. Three-round draft is open. Operating grant: $8.");Save();}
 public void Apply(Simulation s,int opponent){s.Franchise=this;s.OpponentTeam=opponent;s.VenueFromLeague(this,opponent);s.Passing=Passing+Club.CoachOff;s.Running=Running;s.Defense=Defense+Club.CoachDef+(Rating(UserTeam,true)-75)/4;s.Conditioning=Club.CoachFit;s.OpponentName=Teams[opponent].Mascot;s.Postseason=Round>=11&&Round<=13;s.Championship=Round==13;s.BowlName=Round==13?"DOWNFIELD CHAMPIONSHIP BOWL":Round>=11&&Round<=12?"DOWNFIELD PLAYOFF BOWL":"";s.HomeName=Club.Mascot;s.HomeCity=Club.City;}
 public void Dress(List<Player> onField){DressActualRoster(onField);} [XmlIgnore] public int ActiveOpponent;
 public bool Save(){try{EnsureJerseyNumbers();Directory.CreateDirectory(Path.GetDirectoryName(SavePath));XmlSerializer serializer=new XmlSerializer(typeof(Franchise));using(FileStream stream=File.Create(SavePath+".tmp"))serializer.Serialize(stream,this);if(File.Exists(SavePath))File.Replace(SavePath+".tmp",SavePath,SavePath+".bak");else File.Move(SavePath+".tmp",SavePath);return true;}catch(Exception){Notice="Save failed. Keep the game open and check storage access.";return false;}}
 static Franchise Read(string path){XmlSerializer serializer=new XmlSerializer(typeof(Franchise));using(FileStream stream=File.OpenRead(path)){Franchise f=(Franchise)serializer.Deserialize(stream);if(f.Teams.Count!=12||f.UserTeam<0||f.UserTeam>=12||f.Games.Count<66||f.Round<0||f.Round>14)throw new InvalidDataException();f.EnsureLeagueDevelopment();f.EnsureCareer();f.EnsureJerseyNumbers();return f;}}
 public static Franchise Load(Profile old,Roster legacy){try{return Read(SavePath);}catch{try{Franchise f=Read(SavePath+".bak");f.Notice="Recovered previous franchise backup.";return f;}catch{Franchise f=Create(old,legacy);if(File.Exists(SavePath))f.Notice="Franchise save unreadable. Original retained; new club prepared.";return f;}}}
}
}
